                    ["Time"] = 1668886509,
                    ["url"] = "",
                    ["NpcNames"] = {},
                    ["Enabled"] = true,
                    ["Revision"] = 33,
                    ["Options"] = { {
                        ["Type"] = 1,
                        ["Name"] = "Nameplate Color",
                        ["Value"] = { 0, 0.5568627450980392, 0.03529411764705882, 1 },
                        ["Key"] = "nameplateColor",
