                        ["Cast Start"] =
                        "function (self, unitId, unitFrame, envTable, modTable)\n    if not envTable.originalLevel then\n        envTable.originalLevel = unitFrame:GetFrameLevel()\n        envTable.originalAlpha = unitFrame:GetEffectiveAlpha()\n    end\n    \n    -- Create a unique identifier for this unitFrame if it doesn't exist\n    if not modTable.unitKeys[unitFrame] then\n        modTable.unitKeys[unitFrame] = #modTable.unitKeys + 1\n    end\n    \n    if not modTable.castingUnits[unitFrame] then\n        modTable.castCounter = modTable.castCounter + 1\n        envTable.castOrder = modTable.castCounter\n        \n        modTable.castingUnits[unitFrame] = envTable.castOrder\n    else\n        envTable.castOrder = modTable.castingUnits[unitFrame]\n    end\n    \n    -- Use original level as base and add a large offset for casting\n    -- Add unitKey to ensure uniqueness even for simultaneous casts\n    local castingOffset = 100\n    local frameLevel = envTable.originalLevel + castingOffset + (envTable.castOrder * 10) + modTable.unitKeys[unitFrame]\n    \n    if unitFrame.castBar and unitFrame.castBar.isSpecialCast then\n        frameLevel = frameLevel + 50\n    end\n    \n    unitFrame:SetFrameLevel(frameLevel)\n    \n    if modTable.config and modTable.config[\"fullOpacityOnCast\"] then\n        unitFrame:SetAlpha(1.0)\n    end\nend",
                        ["Initialization"] =
                        "function(modTable)\n    modTable.castingUnits = {}\n    modTable.castCounter = 0\n    modTable.unitKeys = {}  -- To store unique identifiers for each unitFrame\nend",
