                    ["Options"] = {},
                    ["HooksTemp"] = {
                        ["Cast Start"] =
                        "function (self, unitId, unitFrame, envTable, modTable)\n    envTable.UpdateCastBarName(unitId, unitFrame.castBar)\nend\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
