                    ["HooksTemp"] = {
                        ["Nameplate Added"] =
                        "function (self, unitId, unitFrame, envTable, modTable)\n    \n    -- need to get this established even if it gets overwritten by threat color later.\n    modTable.GetAndApplyColor(unitFrame)\n    \n    -- unit is not tracked in NPA. not messing with threat colors!\n    if not modTable.IsUnitRelevant(unitFrame) then\n        return\n    end\n    \n    local threatColor = modTable.CheckAggro(unitFrame)\n    if threatColor then\n        -- no aggro/aggro-loss situation.\n        Plater.SetNameplateColor (unitFrame, threatColor)\n        return\n    end\n    \nend",
                        ["Mod Option Changed"] =
                        "function (self, unitId, unitFrame, envTable, modTable)\n    if WeakAuras then\n        WeakAuras.ScanEvents(\"NPA_ClearIgnoreList\")\n    end\nend\n\n\n",
                        ["Player Talent Update"] =
                        "function (self, unitId, unitFrame, envTable, modTable)\n    modTable.colorList = {}\nend",
                        ["Send Comm Message"] =
                        "function (modTable)\n    if _G.NPA_settings and not (modTable.colorsHaveBeenCached  and _G.NPA_cacheUpToDate) then\n        modTable.CacheNPAColors()\n        for _, plateFrame in ipairs (Plater.GetAllShownPlates()) do\n            local unitFrame = plateFrame.unitFrame\n            modTable.GetAndApplyColor(unitFrame)\n        end\n    end\nend\n\n\n",
                        ["Nameplate Updated"] =
                        "function (self, unitId, unitFrame, envTable, modTable)\n    \n    -- unit is not tracked in NPA. not messing with threat colors!\n    if not modTable.IsUnitRelevant(unitFrame) then\n        return\n    end\n    \n    local threatColor = modTable.CheckAggro(unitFrame)\n    if threatColor then\n        -- no aggro/aggro-loss situation\n        Plater.SetNameplateColor (unitFrame, threatColor)\n        return\n    end\n    \n    local color =  modTable.colorList[unitFrame]\n    Plater.SetNameplateColor (unitFrame, color)\nend",
                        ["Initialization"] =
                        "function (modTable)\n    \n    modTable.IsUnitRelevant = function(unitFrame)\n        return modTable.colorList[unitFrame] and true or false\n    end\n    \n    \n    modTable.UpdatePriorityList = function()\n        modTable.npaPriorityList  = { }\n        \n        local npaCustomOrder = {\n            [\"important\"] = modTable.config.prioImportant,\n            [\"frontal\"] = modTable.config.prioFrontal,\n            [\"damage\"] = modTable.config.prioDamage,\n            [\"kick\"] = modTable.config.prioKick,\n            [\"stun\"] = modTable.config.prioStun,\n            [\"avoid\"] = modTable.config.prioAvoid,\n            [\"tank\"] = modTable.config.prioTank,\n            [\"alert\"] = modTable.config.prioAlert,\n            [\"swirly\"] = modTable.config.prioSwirly,\n        }\n        \n        for i=1,8 do\n            for spell, nr in pairs(npaCustomOrder ) do\n                if nr == i then\n                    table.insert(modTable.npaPriorityList, spell)\n                end\n                \n            end\n            \n        end\n    end\n    modTable.UpdatePriorityList() \n    \n    modTable.npaSpellTypes = {\n        [\"kick\"] = modTable.config.kick,\n        [\"stun\"] = modTable.config.stun,\n        [\"frontal\"] = modTable.config.frontal,\n        [\"damage\"] = modTable.config.damage,\n        [\"tank\"] = modTable.config.tank,\n        [\"avoid\"] = modTable.config.avoid,\n        [\"swirly\"] = modTable.config.swirly,\n        [\"alert\"] = modTable.config.alert,\n        [\"important\"] = modTable.config.important,\n    }\n    \n    modTable.GetNPAColor = function(r,g,b)\n        -- this code has been lifted from iskolbin on github: \n        -- https://github.com/iskolbin/lhsx\n        -- iskolbin@gmail.com\n        \n        -- converting RGB to HSV\n        local M, m = max( r, g, b ), min( r, g, b )\n        local C = M - m\n        local K\n        local h = 0.0\n        if C ~= 0.0 then\n            K = 1.0/(6.0 * C)\n            if M == r then     h = ((g - b) * K) % 1.0\n            elseif M == g then h = (b - r) * K + 1.0/3.0\n            else               h = (r - g) * K + 2.0/3.0\n            end\n        end\n        local s,v = M == 0.0 and 0.0 or C / M, M\n        \n        -- when lowering the brightness we can just reduce luminance.\n        if modTable.config.brightness < 1 then\n            v = v * modTable.config.brightness\n        end\n        \n        -- applying user saturation\n        s = s * modTable.config.saturation\n        \n        -- shifting the hue\n        local hueOffset = modTable.config.hue\n        if hueOffset > 0 then\n            h = math.fmod(h+hueOffset, 1)\n        end\n        \n        -- converting back to RGB\n        C = v * s\n        m = v - C\n        if h == h then\n            local h_ = (h % 1.0) * 6\n            local X = C * (1 - abs(h_ % 2 - 1))\n            C, X = C + m, X + m\n            if     h_ < 1 then r, g, b = C, X, m\n            elseif h_ < 2 then r, g, b = X, C, m\n            elseif h_ < 3 then r, g, b = m, C, X\n            elseif h_ < 4 then r, g, b = m, X, C\n            elseif h_ < 5 then r, g, b = X, m, C\n            else               r, g, b = C, m, X\n            end\n        end\n        \n        -- when increasing brightness, this will ensure that the max value will make the nameplate white.\n        -- that way the colors appear less saturated as brightness goes up.\n        if modTable.config.brightness > 1 then\n            local add = modTable.config.brightness * (modTable.config.brightness-1)\n            r,g,b = r+add, g+add, b+add\n        end\n        \n        return r, g, b\n    end\n    \n    modTable.npaColors = {}\n    -- caching the processed colors in the list above.\n    modTable.CacheNPAColors = function()\n        for _,spellType in pairs(modTable.npaPriorityList) do\n            local r,g,b,a = unpack(_G.NPA_settings[spellType][1])\n            r,g,b = modTable.GetNPAColor(r,g,b)\n            local color = {r,g,b,a} \n            modTable.npaColors [spellType] = color\n        end\n        modTable.colorsHaveBeenCached = true\n        setglobal(\"NPA_cacheUpToDate\", true)\n    end    \n    \n    modTable.GetAndApplyColor = function(unitFrame)\n        \n        local npcId = unitFrame.namePlateNpcId\n        if _G.NPA_mergedList and _G.NPA_mergedList[npcId] then\n            local NPA_list = _G.NPA_mergedList\n            local color\n            \n            for _,spellType in pairs(modTable.npaPriorityList) do\n                if modTable.npaSpellTypes[spellType] then\n                    for _, spellTypeUser in pairs(NPA_list[npcId]) do\n                        if type(spellTypeUser) == \"string\" then\n                            spellTypeUser = string.lower(spellTypeUser)\n                            local spellTypeList = {}\n                            for str in string.gmatch(spellTypeUser, \"[^/]+\") do\n                                table.insert(spellTypeList, str)\n                            end\n                            spellTypeUser = spellTypeList[1]\n                            if string.match(spellTypeUser, spellType)\n                            and not string.match(spellTypeUser, \"nosymbol\") then\n                                if ( spellType == \"tank\" and _G.NPA_settings[\"isTank\"] )\n                                or spellType ~= \"tank\" then\n                                    if ( modTable.config.obeySymbols and _G.NPA_settings[\"iconSettings\"][spellType] )\n                                    or not modTable.config.obeySymbols then\n                                        color = modTable.npaColors[spellType]\n                                        Plater.SetNameplateColor (unitFrame, color)\n                                        modTable.colorList[unitFrame] = color\n                                        WeakAuras.ScanEvents(\"NPA_HideSymbol\", unitFrame.unit, npcId, spellType)\n                                        return\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n                \n            end\n        end\n        Plater.RefreshNameplateColor(unitFrame)\n        modTable.colorList[unitFrame] = false\n    end\n    \n    modTable.colorList = {}\n    \n    -- original code by Kastfall-Azralon\n    -- https://wago.io/P35nCfDqx\n    function modTable.CheckAggro (unitFrame)\n        --if the player isn't in combat, ignore this check\n        if (not Plater.IsInCombat()) \n        or (UnitPlayerControlled(unitFrame.unit)) \n        or (not unitFrame.InCombat) \n        or (not _G.NPA_settings)\n        or (not _G.NPA_settings.groupHasTank) then\n            return false\n        end\n        \n        --player is a tank?\n        if (Plater.PlayerIsTank) then\n            --player isn't tanking this unit?\n            if (not unitFrame.namePlateThreatIsTanking) then\n                --check if a second tank is tanking it\n                if (Plater.ZoneInstanceType == \"raid\") then\n                    --return a list with the name of tanks in the raid\n                    local tankPlayersInTheRaid = Plater.GetTanks()\n                    \n                    --get the target name of this unit\n                    local unitTargetName = UnitName (unitFrame.targetUnitID)\n                    \n                    --check if the unit isn't targeting another tank in the raid and paint the color\n                    if (not tankPlayersInTheRaid [unitTargetName]) then\n                        return Plater.db.profile.tank.colors.noaggro\n                    else\n                        --another tank is tanking this unit\n                        return false\n                    end\n                    \n                else\n                    return Plater.db.profile.tank.colors.noaggro\n                end\n            end\n            \n        else\n            --player is a dps or healer\n            if (unitFrame.namePlateThreatIsTanking) then\n                return Plater.db.profile.dps.colors.aggro\n            end\n        end   \n        return false\n    end\n    \nend",
                        ["Deinitialization"] =
                        "function (modTable)\n    \n    if WeakAuras then\n        WeakAuras.ScanEvents(\"NPA_ClearIgnoreList\")\n    end\n    \nend"
                    },
                    ["version"] = 12
                }, {
                    ["OptionsValues"] = {
                        ["ignore_color_changes"] = true,
                        ["testing"] = false
                    },
                    ["LastHookEdited"] = "",
                    ["Hooks"] = {
                        ["Nameplate Updated"] =
                        "function (self, unitId, unitFrame, envTable, modTable)\n    local unitFrameGUID = UnitGUID(self.unit)\n    \n    if modTable.shouldIgnoreNpcId(self) or\n    not Plater.IsInCombat() or \n    not self.InCombat or \n    UnitPlayerControlled(self.unit)\n    then\n        envTable.hideAggroOverlay(self);\n        return\n    end        \n    \n    local targetGUID = UnitGUID(self.targetUnitID or '')\n    \n    if (targetGUID and targetGUID ~= self._lastTargetUnitID) then\n        self._lastTargetUnitID = targetGUID\n        if (modTable.playerHasAggro(self)) then\n            envTable.showAggroOverlay(self);\n        else\n            envTable.hideAggroOverlay(self);\n        end\n    end\nend",
                        ["Nameplate Added"] =
                        "function (self, unitId, unitFrame, envTable, modTable)\n    local unitFrameGUID = UnitGUID(self.unit)\n    \n    if modTable.shouldIgnoreNpcId(self) or\n    not Plater.IsInCombat() or \n    not self.InCombat or \n    UnitPlayerControlled(self.unit)\n    then\n        envTable.hideAggroOverlay(self);\n        return\n    end        \n    \n    local targetGUID = UnitGUID(self.targetUnitID or '')\n    \n    if (targetGUID and targetGUID ~= self._lastTargetUnitID) then\n        self._lastTargetUnitID = targetGUID\n        if (modTable.playerHasAggro(self)) then\n            envTable.showAggroOverlay(self);\n        else\n            envTable.hideAggroOverlay(self);\n        end\n    end\nend",
                        ["Initialization"] =
                        "function (modTable)\n    --[[\n        Checks if npcId should be ignored or not\n\n        @param  {Plater.unitFrame}  unitFrame\n\n        @return {bool}\n    --]]\n    function modTable.shouldIgnoreNpcId(unitFrame)\n        local unitId = unitFrame.unitId\n        \n        return unitFrame.isPerformanceUnit\n    end\n    \n    --[[\n        Checks if player has aggro\n\n        @return {Boolean}\n    --]]\n    function modTable.playerHasAggro(unitFrame)\n        if (modTable.config['testing'] == true) then\n            if (not modTable.config['ignore_color_changes']) then\n                Plater.SetNameplateColor (unitFrame, Plater.db.profile.tank.colors.noaggro);\n            end\n            \n            return true;\n        end\n        \n        if (not Plater.IsInCombat()) then\n            return false;\n        end\n        \n        if (not unitFrame.InCombat) then\n            return false;\n        end\n        \n        if (UnitPlayerControlled(unitFrame.unit)) then\n            return false;\n        end\n        \n        if (Plater.PlayerIsTank) then\n            if (not unitFrame.namePlateThreatIsTanking) then\n                if (not modTable.config['ignore_color_changes']) then\n                    Plater.SetNameplateColor (unitFrame, Plater.db.profile.tank.colors.noaggro);\n                end\n                \n                return true;\n            else\n                return false;\n            end\n        else\n            local tanks = Plater.GetTanks();\n            local targetOfTarget = UnitName(unitFrame.targetUnitID or '');\n            local targetOfTargetIsPlayer = targetOfTarget == UnitName('player');\n            local unitIsNotAttackingTank = false;\n            \n            if (Plater.db.profile.aggro_can_check_notank) then\n                unitIsNotAttackingTank = (\n                    targetOfTarget and \n                    not tanks[targetOfTarget]\n                );\n            end\n            \n            if (unitFrame.namePlateThreatIsTanking or unitIsNotAttackingTank) then\n                if (Plater.db.profile.aggro_can_check_notank and unitIsNotAttackingTank and not targetOfTargetIsPlayer) then\n                    if (not modTable.config['ignore_color_changes']) then\n                        Plater.SetNameplateColor (unitFrame, Plater.db.profile.dps.colors.notontank);\n                    end\n                else\n                    if (not modTable.config['ignore_color_changes']) then\n                        Plater.SetNameplateColor (unitFrame, Plater.db.profile.dps.colors.aggro);\n                    end\n                end\n                \n                return true;\n            else\n                return false;\n            end\n        end\n    end\nend",
                        ["Constructor"] =
                        "function (self, unitId, unitFrame, envTable, modTable)\n    local textureHeight = self.healthBar:GetHeight() * 4;\n    local textureWidth = textureHeight * 2;\n    \n    unitFrame._currentColor = nil;\n    \n    --[[\n        @var {Table}\n    --]]\n    envTable.TEXTURE_CONFIG = {\n        ['height'] = textureHeight,\n        ['width'] = textureWidth\n    };\n    \n    --[[\n        @var {String}\n    --]]\n    envTable.TEXTURE_PATH = [[Interface\\Addons\\GennUI\\media\\textures\\Aggro.tga]];\n    \n    --[[ \n        Creates the overlay frame if it doesn't exist\n    \n        @param  {Plater.unitFrame}  unitFrame\n    \n        @return {void}\n    --]]\n    function envTable.createFrameIfNotExists(unitFrame)\n        local healthBar = unitFrame.healthBar;\n        \n        if (not healthBar.aggroOverlayLeft) then\n            healthBar.aggroOverlayLeft = envTable.createOverlayFrame(\n                healthBar, \n                'left', \n                -10 - math.floor(envTable.TEXTURE_CONFIG['width'] / 2), \n                0\n            );\n            \n            healthBar.aggroOverlayLeft.overlayTexture:SetTexCoord(0, 1, 1, 0);\n        end\n        \n        if (not healthBar.aggroOverlayRight) then\n            healthBar.aggroOverlayRight = envTable.createOverlayFrame(\n                healthBar, \n                'right', \n                10 + math.floor(envTable.TEXTURE_CONFIG['width'] / 2), \n                0\n            );\n            \n            healthBar.aggroOverlayRight.overlayTexture:SetTexCoord(1, 0, 0, 1);\n        end\n        \n        if (not healthBar.targetOfTargetText) then\n            unitFrame._currentTargetName = '';\n            healthBar.targetOfTargetText = envTable.createTargetOfTargetFrame(\n                healthBar\n            );\n        end\n    end\n    \n    --[[\n        Creates the target of target text frame\n\n        @param  {Plater.unitFrame.healthBar}  healthBar\n\n        @return {Frame}\n    --]]\n    function envTable.createTargetOfTargetFrame(healthBar)\n        local textFrame = Plater:CreateLabel(healthBar);        \n        textFrame:SetPoint('topleft', healthBar, 'topleft', 0, 5);\n        textFrame.textcolor = 'white';\n        textFrame.textsize = 7;\n        textFrame.outline = 'OUTLINE';\n        textFrame:Show();\n        \n        return textFrame;\n    end\n    \n    --[[ \n        Creates the overlay frame\n    \n        @param  {Plater.unitFrame.healthbar}  healthBar\n        @param  {String}  originPoint\n        @param  {Number}  posX\n        @param  {Number}  posY\n    \n        @return {Frame}\n    --]]\n    function envTable.createOverlayFrame(healthBar, originPoint, posX, posY)\n        local overlayFrame = CreateFrame('frame', nil, healthBar);\n        overlayFrame:SetFrameLevel(healthBar:GetFrameLevel());\n        overlayFrame:SetPoint(originPoint, healthBar, originPoint, posX, posY);\n        \n        local overlayColorR, overlayColorG, overlayColorB = DetailsFramework:ParseColors (Plater.db.profile.tank.colors.noaggro);\n        local overlayTexture = Plater:CreateImage(overlayFrame, envTable.TEXTURE_PATH);\n        overlayTexture:SetVertexColor(overlayColorR, overlayColorG, overlayColorB);\n        overlayTexture:SetPoint(originPoint, healthBar, originPoint, posX, posY);\n        overlayTexture:SetSize(envTable.TEXTURE_CONFIG['width'], envTable.TEXTURE_CONFIG['height']);\n        \n        overlayFrame.overlayTexture = overlayTexture;\n        overlayFrame:Show();\n        \n        return overlayFrame;\n    end\n    \n    --[[\n        Creates the target of target text frame\n\n        @param  {Plater.unitFrame}  unitFrame\n        @param  {String}  targetUnitID\n\n        @return {Frame}\n    --]]\n    function envTable.updateTargetOfTarget(unitFrame, targetUnitID)\n        local targetText = unitFrame.healthBar.targetOfTargetText;\n        local targetUnitName = UnitName(targetUnitID or '') or '';\n        \n        if modTable.config['disableTargetOfTarget'] then\n            targetUnitName = ' '\n        end\n        \n        if (targetUnitName == UnitName('player')) then\n            targetUnitName = '';\n        end\n        \n        if (unitFrame._currentTargetName == targetUnitName) then\n            return;\n        end\n        \n        unitFrame._currentTargetName = targetUnitName;\n        targetText.text = targetUnitName;\n        \n        local _, class = UnitClass(targetUnitID or '');\n        \n        if (class and UnitIsPlayer(targetUnitID or '')) then\n            targetText.textcolor = DetailsFramework:ParseColors(class);\n        else\n            targetText.textcolor = Plater.db.profile.castbar_target_color;\n        end\n    end\n    \n    --[[\n        Updates the aggro overlay texture color\n\n        @param  {Plater.unitFrame}  unitFrame\n\n        @return {void}\n    --]]\n    function envTable.updateAggroOverlayColor(unitFrame)\n        local colorR, colorG, colorB, colorA = DetailsFramework:ParseColors(unitFrame.healthBar:GetColor());\n        local qualifiedColor = envTable.qualifyColor(colorR, colorG, colorB, colorA);\n        \n        if (unitFrame._currentColor == qualifiedColor) then\n            return;\n        end\n        \n        unitFrame._currentColor = qualifiedColor;\n        \n        unitFrame.healthBar.aggroOverlayRight.overlayTexture:SetVertexColor(colorR, colorG, colorB);\n        unitFrame.healthBar.aggroOverlayLeft.overlayTexture:SetVertexColor(colorR, colorG, colorB);\n    end\n    \n    --[[\n        Qualifies a color to a cacheable string\n\n        @param  {Number}  r\n        @param  {Number}  g\n        @param  {Number}  b\n        @param  {Number}  a\n\n        @return {String}\n    --]]\n    function envTable.qualifyColor(r, g, b, a)\n        return tostring(r) .. tostring(g) .. tostring(b) .. tostring(a);\n    end\n    \n    --[[ \n        Shows the overlay frames\n\n        @param  {Plater.unitFrame}  unitFrame\n\n        @return {void}\n    --]]\n    function envTable.showAggroOverlay(unitFrame)\n        envTable.createFrameIfNotExists(unitFrame);\n        envTable.updateTargetOfTarget(unitFrame, unitFrame.targetUnitID);\n        unitFrame.healthBar.aggroOverlayLeft.overlayTexture:Show();\n        unitFrame.healthBar.aggroOverlayRight.overlayTexture:Show();\n        envTable.updateAggroOverlayColor(unitFrame);\n    end\n    \n    --[[ \n        Hides the overlay frames\n\n        @return {void}\n    --]]\n    function envTable.hideAggroOverlay(unitFrame)\n        envTable.createFrameIfNotExists(unitFrame);\n        envTable.updateTargetOfTarget(unitFrame, nil);\n        unitFrame.healthBar.aggroOverlayLeft.overlayTexture:Hide();\n        unitFrame.healthBar.aggroOverlayRight.overlayTexture:Hide();\n        envTable.updateAggroOverlayColor(unitFrame);\n    end\nend"
                    },
