                    ["OptionsValues"] = {},
                    ["LastHookEdited"] = "Cast Start",
                    ["UID"] = "0x64123ca337069ce",
                    ["Hooks"] = {
                        ["Initialization"] =
                        "function(modTable)\n    modTable.castingUnits = {}\n    modTable.castCounter = 0\nend",
                        ["Cast Start"] =
                        "function (self, unitId, unitFrame, envTable, modTable)\n    if not envTable.originalLevel then\n        envTable.originalLevel = unitFrame:GetFrameLevel()\n        envTable.originalAlpha = unitFrame:GetEffectiveAlpha()\n    end\n    \n    -- Check if the unitFrame is already in castingUnits\n    if not modTable.castingUnits[unitFrame] then\n        modTable.castCounter = modTable.castCounter + 1 -- Increment the counter\n        envTable.castOrder = modTable.castCounter      -- Save the cast order\n        \n        -- Add unitFrame to castingUnits with its castOrder\n        modTable.castingUnits[unitFrame] = envTable.castOrder\n    else\n        -- Retrieve the existing castOrder\n        envTable.castOrder = modTable.castingUnits[unitFrame]\n    end\n    \n    -- Set the frame level of the casting unit based on castOrder\n    -- Using a higher base level and more spacing to prevent overlaps\n    local frameLevel = 500 + (envTable.castOrder * 10)\n    \n    if unitFrame.castBar and unitFrame.castBar.isSpecialCast then\n        frameLevel = frameLevel + 50\n    end\n    \n    unitFrame:SetFrameLevel(frameLevel)\n    \n    if modTable.config and modTable.config[\"fullOpacityOnCast\"] then\n        unitFrame:SetAlpha(1.0)\n    end\nend",
                        ["Cast Stop"] =
                        "function (self, unitId, unitFrame, envTable, modTable)\n  if envTable.originalLevel then\n      -- Remove unitFrame from castingUnits\n      modTable.castingUnits[unitFrame] = nil\n\n      -- Restore original frame level and alpha\n      unitFrame:SetFrameLevel(envTable.originalLevel)\n      unitFrame:SetAlpha(envTable.originalAlpha)\n      envTable.originalLevel = nil\n      envTable.originalAlpha = nil\n      envTable.castOrder = nil\n  end\nend"
