                        ["Initialization"] =
                        "function (modTable)\n    \n    modTable.useTargetColor             = modTable.config.targetEnabled\n    modTable.targetColor                = modTable.config.targetColor\n    modTable.ignoreTargetColorOnPlayers = modTable.config.ignoreTargetOnPlayers\n    modTable.useFocusColor              = modTable.config.focusEnabled\n    modTable.focusColor                 = modTable.config.focusColor\n    \n    modTable.colorHealthBar             = modTable.config.colorHealthBar\n    modTable.colorNameText              = modTable.config.colorName\n    modTable.showRaidMarkColors         = modTable.config.raidMarkColors\n    modTable.useThreatColors            = modTable.config.threatColors -- use threat colors if you are tank without aggro or dps with aggro\n    modTable.colorRares                 = modTable.config.rareEnabled\n    \n    -- you can replace any color text line with 'nil' to skip this mark from being colored, e.g.:    nil, --star\n    modTable.colorByMark = {\n        [1] = \"#d9cf45\", -- Yellow Star\n        [2] = \"#ed820f\", -- Orange Circle\n        [3] = \"#b30fd6\", -- Purple Diamond\n        [4] = \"#24a824\", -- Green Triangle\n        [5] = \"#99bfd9\", -- Silver Moon\n        [6] = \"#00a3ff\", -- Blue Square\n        [7] = \"#d12e2e\", -- Red Cross\n        [8] = \"#e3d4bd\", -- White Skull\n    }\n    \n    -- rare-type colors\n    modTable.rareColors = {\n        --[\"elite\"] = \"darkgoldenrod\",\n        [\"rareelite\"] = \"goldenrod\",\n        [\"rare\"] = \"silver\",\n        [\"worldboss\"] = \"darkmagenta\",\n    }\n    \n    modTable.npcColors = {\n        -- Mythic Plus Affixes\n        [229296] = modTable.config.affixEnabled and modTable.config.affixColor or nil, -- Orb of Ascendance\n        [229537] = modTable.config.affixEnabled and modTable.config.affixColor or nil, -- Void Emissary\n        \n        -- TWW2: Cinderbrew Meadery\n        [210264] = modTable.config.t3Mobs, -- Bee Wrangler\n        [214673] = mo