213937] = modTable.config.t1Mobs, -- Rasha'nan\n        [214762] = modTable.config.t1Mobs, -- Nightfall Commander\n        \n        [213892] = modTable.config.t3Mobs, -- Nightfall Shadowmage\n        [213893] = modTable.config.t3Mobs, -- Nightfall Darkcaster\n        [213905] = modTable.config.t3Mobs, -- Animated Darkness\n        [223994] = modTable.config.t3Mobs, -- Nightfall Shadowmage\n        [228540] = modTable.config.t3Mobs, -- Nightfall Shadowmage\n        \n        [213894] = modTable.config.t4Mobs, -- Nightfall Curseblade\n        [213895] = modTable.config.t4Mobs, -- Nightfall Shadowalker\n        \n        -- TWW1: The Stonevault\n        [213217] = modTable.config.t1Mobs, -- Speaker Brokk\n        \n        [212389] = modTable.config.t3Mobs, -- Cursedheart Invader\n        [212403] = modTable.config.t3Mobs, -- Cursedheart Invader\n        [212453] = modTable.config.t3Mobs, -- Ghastly Voidsoul\n        [213338] = modTable.config.t3Mobs, -- Forgebound Mender\n        [214066] = modTable.config.t3Mobs, -- Cursedforge Stoneshaper\n        [214350] = modTable.config.t3Mobs, -- Turned Speaker\n        [221979] = modTable.config.t3Mobs, -- Void Bound Howler\n        [224962] = modTable.config.t3Mobs, -- Cursedforge Mender\n        \n        [212764] = modTable.config.t4Mobs, -- Engine Speaker\n        [212405] = modTable.config.t4Mobs, -- Aspiring Forgehand\n        \n        -- TWW1: The Necrotic Wake\n        [162693] = modTable.config.t1Mobs, -- Nalthor the Rimebinder\n        [163157] = modTable.config.t1Mobs, -- Amarth\n        [165137] = modTable.config.t1Mobs, -- Zolramus Gatekeeper\n        [165824] = modTable.config.t1Mobs, -- Nar'zudah\n        [165919] = modTable.config.t1Mobs, -- Skeletal Marauder\n        [173044] = modTable.config.t1Mobs, -- Stitching Assistant\n        \n        [163126] = modTable.config.t3Mobs, -- Brittlebone Mage\n        [163128] = modTable.config.t3Mobs, -- Zolramus Sorcerer\n        [163618] = modTable.config.t3Mobs, -- Zolramus Necromancer\n        [165222] = modTable.config.t3Mobs, -- Zolramus Bonemender\n        [165872] = modTable.config.t3Mobs, -- Flesh Crafter\n        [166302] = modTable.config.t3Mobs, -- Corpse Harvester\n        [173016] = modTable.config.t3Mobs, -- Corpse Collector\n        \n        [163121] = modTable.config.t4Mobs, -- Stitched Vanguard\n        [163619] = modTable.config.t4Mobs, -- Zolramus Bonecarver\n        \n        [165138] = modTable.config.t5Mobs, -- Blight Bag\n        [166264] = modTable.config.t5Mobs, -- Spare Parts\n        [166266] = modTable.config.t5Mobs, -- Spare Parts #2\n        [171500] = modTable.config.t5Mobs, -- Shuffling Corpse\n        \n        -- TWW1: Nerub-ar Palace\n        [217491] = modTable.config.t1Mobs, -- Skeinspinner Takazj\n        \n        \n        -- TWW: Awakening the Machine\n        [229695] = modTable.config.t3Mobs, -- Corrupted Machinist\n        \n        [229769] = modTable.config.t4Mobs, -- Medbot\n        \n        -- TWW: Delves\n        [221896] = modTable.config.t1Mobs, -- Web General Ab'enar\n        [217208] = modTable.config.t1Mobs, -- Zekvir\n        [228030] = modTable.config.t1Mobs, -- Sir Finley Mrrgglton\n        \n        [208244] = modTable.config.t3Mobs, -- Nerubian Threadmancer\n        [208242] = modTable.config.t3Mobs, -- Nerubian Darkcaster\n        [203878] = modTable.config.t3Mobs, -- Kobold Mystic\n        -- [204127] = modTable.config.t3Mobs, -- Kobold Taskfinder\n        \n        [226625] = modTable.config.t5Mobs, -- Cave Skipper\n    }\n    \n    modTable.aggroTracked = {\n        -- Some Mobs that doesn't have aggro or are important to track their aggro\n        [80875] = true, -- Bombsquad\n        [150547] = true, -- Scrapbone Grunter\n        [152033] = true, -- Inconspicuous Plant\n        [152703] = true, -- Walkie Shockie X1\n        [153196] = true, -- Scrapbone Grunter\n        [163746] = true, -- Walkie Shockie X1\n        [174773] = true, -- Spiteful Shade\n        [177500] = true, -- Corsair Brute\n        [178388] = true, -- Bazaar Strongarm\n    }\n    \n    function modTable.UpdateColor (unitFrame, envTable)\n        if not unitFrame or unitFrame.IsNpcWithoutHealthbar or unitFrame.IsFriendlyPlayerWithoutHealthbar or unitFrame.DenyColorChange then return end\n        \n        local forceAggroColor = modTable.aggroTracked [unitFrame.namePlateNpcId] or modTable.aggroTracked [unitFrame.namePlateUnitName] or modTable.aggroTracked [unitFrame.namePlateUnitNameLower]\n        \n        if forceAggroColor then\n            local unit = unitFrame.targetUnitID\n            if UnitExists(unit) and UnitIsPlayer(unit) then\n                if UnitGroupRolesAssigned(unit) == \"TANK\" then\n                    if UnitIsUnit(unit, \"player\") or unitFrame.namePlateThreatStatus == 3 then\n                        Plater.SetNameplateColor (unitFrame, Plater.db.profile.tank.colors.aggro)\n                        return\n                    else\n                        if Plater.PlayerIsTank then\n                            Plater.SetNameplateColor (unitFrame, Plater.db.profile.tank.colors.anothertank)\n                            return\n                        end\n                    end\n                else\n                    if UnitIsUnit(unit, \"player\") or unitFrame.namePlateThreatStatus == 3 then\n                        Plater.SetNameplateColor (unitFrame, Plater.db.profile.dps.colors.aggro)\n                        return\n                    end\n                end\n            end\n        end\n        \n        if (modTable.useThreatColors and Plater.IsInCombat() and unitFrame.InCombat) then\n            if (Plater.PlayerIsTank) then\n                if (not unitFrame.namePlateThreatIsTanking or unitFrame.namePlateThreatStatus == 2) then\n                    return\n                end\n            else\n                if (unitFrame.namePlateThreatIsTanking or unitFrame.namePlateThreatStatus == 1) then\n                    return\n                end\n            end\n        end\n        \n        if modTable.useTargetColor then\n            local unitIsPlayer = unitFrame.ActorType == \"friendlyplayer\" or unitFrame.ActorType == \"enemyplayer\"\n            if unitFrame.namePlateIsTarget then\n                if not unitIsPlayer or (not modTable.ignoreTargetColorOnPlayers and unitIsPlayer) then\n                    if modTable.colorHealthBar then\n                        Plater.SetNameplateColor (unitFrame, modTable.targetColor)\n                    end\n                    if modTable.colorNameText then\n                        Plater:SetFontColor (unitFrame.unitName, Plater:ParseColors(modTable.targetColor))\n                    end\n                    envTable.HasRaidMark = nil\n                    envTable.isTarget = true\n                    envTable.wasTarget = false\n                end\n                return\n            elseif envTable.isTarget then\n                envTable.isTarget = false\n                envTable.wasTarget = true\n            end\n        end\n        \n        if modTable.useFocusColor then\n            if UnitIsUnit (unitFrame.namePlateUnitToken, \"focus\") then\n                if modTable.colorHealthBar then\n                    Plater.SetNameplateColor (unitFrame, modTable.focusColor)\n                end\n                if modTable.colorNameText then\n                    Plater:SetFontColor (unitFrame.unitName, Plater:ParseColors(modTable.focusColor))\n                end\n                envTable.HasRaidMark = nil\n                envTable.isFocus = true\n                envTable.wasFocus = false\n                return\n            elseif envTable.isFocus then\n                envTable.isFocus = false\n                envTable.wasFocus = true\n            end\n        end\n        \n        -- from \"Color by Raid Mark\"\n        local raidMark = nil\n        if modTable.showRaidMarkColors and unitFrame.unit then\n            raidMark = Plater.GetRaidMark (unitFrame)\n        end\n        \n        if (raidMark and modTable.colorByMark [raidMark]) then\n            \n            if modTable.colorHealthBar then\n                Plater.SetNameplateColor (unitFrame, modTable.colorByMark [raidMark])\n            end\n            if modTable.colorNameText then\n                Plater:SetFontColor (unitFrame.unitName, Plater:ParseColors(modTable.colorByMark [raidMark]))\n            end\n            envTable.HasRaidMark = true\n            return\n        end\n        \n        --attempt to get the color from the unit color list\n        local color = modTable.npcColors [unitFrame.namePlateUnitNameLower] or modTable.npcColors [unitFrame.namePlateUnitName] or modTable.npcColors [unitFrame.namePlateNpcId] or (modTable.colorRares and modTable.rareColors[UnitClassification(unitFrame.namePlateUnitToken)])\n        \n        -- Automatically detect T2 mobs by level\n        if (not color) then\n            local playerLevel = UnitLevel(\"player\")\n            local unitLevel = UnitLevel(unitFrame.unit)\n            \n            if (Plater.ZoneInstanceType == \"party\" or Plater.ZoneInstanceType == \"scenario\") then\n                -- In dungeons, anything higher level than the player is a lieutenant/boss\n                if (playerLevel < unitLevel) then\n                    color = modTable.config.t2Mobs\n                end\n            elseif (Plater.ZoneInstanceType == \"raid\") then\n                -- In raids, anything two or more levels higher than the player or ?? (-1) is a lieutenant/boss\n                if ((playerLevel < unitLevel - 1) or (unitLevel == -1)) then\n                    color = modTable.config.t2Mobs\n                end\n            end\n        end\n        \n        --if the color exists, set the health bar color\n        if (color) then\n            \n            if modTable.colorHealthBar then\n                Plater.SetNameplateColor (unitFrame, color)\n            end\n            if modTable.colorNameText then\n                Plater:SetFontColor (unitFrame.unitName, Plater:ParseColors(color))\n            end\n            envTable.HasRaidMark = nil\n            \n        elseif envTable.HasRaidMark or envTable.wasTarget or envTable.wasFocus then\n            \n            if unitIsPlayer then\n                Plater.FindAndSetNameplateColor (unitFrame)\n            else\n                Plater.RefreshNameplateColor (unitFrame)\n            end\n            if modTable.colorNameText then\n                --Plater.UpdatePlateText (unitFrame.PlateFrame, Plater.db.profile.plate_config[unitFrame.ActorType], false)\n                modTable.resetNameColor(unitFrame)\n            end\n            envTable.HasRaidMark = nil\n            envTable.wasTarget = false\n            envTable.wasFocus = false\n            \n        end\n    end\n    \n    function modTable.resetNameColor(unitFrame)\n        local plateFrame = unitFrame.PlateFrame\n        local nameString = unitFrame.unitName\n        local plateConfigs = Plater.db.profile.plate_config[unitFrame.ActorType]\n        local ACTORTYPE_FRIENDLY_PLAYER = \"friendlyplayer\"\n        \n        if (Plater.db.profile.plate_config [ACTORTYPE_FRIENDLY_PLAYER].actorname_use_guild_color and plateFrame.playerGuildName == Plater.PlayerGuildName) then\n            \n            Plater:SetFontColor (nameString, unpack(Plater.db.profile.plate_config [ACTORTYPE_FRIENDLY_PLAYER].actorname_guild_color))\n            \n        elseif (Plater.db.profile.plate_config [ACTORTYPE_FRIENDLY_PLAYER].actorname_use_friends_color and Plater.FriendsCache [plateFrame.namePlateUnitName]) then\n            \n            Plater:SetFontColor (nameString, unpack(Plater.db.profile.plate_config [ACTORTYPE_FRIENDLY_PLAYER].actorname_friend_color))\n            \n        elseif (plateFrame.actorType == ACTORTYPE_FRIENDLY_PLAYER and Plater.db.profile.plate_config [ACTORTYPE_FRIENDLY_PLAYER].actorname_use_class_color) then\n            local _, unitClass = UnitClass (unitFrame.namePlateUnitToken)\n            \n            if (unitClass) then\n                local color = RAID_CLASS_COLORS [unitClass]\n                Plater:SetFontColor (nameString, color.r, color.g, color.b)\n            else\n                Plater:SetFontColor (nameString, plateConfigs.actorname_text_color)\n            end\n            \n        else\n            Plater:SetFontColor (nameString, plateConfigs.actorname_text_color)\n        end\n    end\n    \nend\n\n\n\n\n",
                        ["Target Changed"] =
                        "function (self, unitId, unitFrame, envTable, modTable)\n    if modTable.useTargetColor then\n        modTable.UpdateColor (unitFrame, envTable)\n    end\nend\n\n\n\n\n\n\n"
