                    } },
                    ["HooksTemp"] = {
                        ["Nameplate Updated"] =
                        "function (self, unitId, unitFrame, envTable, modTable)\n    if not unitFrame.coloredByScript  then\n        modTable.UpdateColor (unitFrame, envTable)\n    end\nend",
                        ["Initialization"] =
                        "function (modTable)\n    \n    modTable.useTargetColor             = modTable.config.targetEnabled\n    modTable.targetColor                = modTable.config.targetColor\n    modTable.ignoreTargetColorOnPlayers = modTable.config.ignoreTargetOnPlayers\n    modTable.useFocusColor              = modTable.config.focusEnabled\n    modTable.focusColor                 = modTable.config.focusColor\n    \n    modTable.colorHealthBar             = modTable.config.colorHealthBar\n    modTable.colorNameText              = modTable.config.colorName\n    modTable.showRaidMarkColors         = modTable.config.raidMarkColors\n    modTable.useThreatColors            = modTable.config.threatColors -- use threat colors if you are tank without aggro or dps with aggro\n    modTable.colorRares                 = modTable.config.rareEnabled\n    \n    -- you can replace any color text line with 'nil' to skip this mark from being colored, e.g.:    nil, --star\n    modTable.colorByMark = {\n        [1] = \"#d9cf45\", -- Yellow Star\n        [2] = \"#ed820f\", -- Orange Circle\n        [3] = \"#b30fd6\", -- Purple Diamond\n        [4] = \"#24a824\", -- Green Triangle\n        [5] = \"#99bfd9\", -- Silver Moon\n        [6] = \"#00a3ff\", -- Blue Square\n        [7] = \"#d12e2e\", -- Red Cross\n        [8] = \"#e3d4bd\", -- White Skull\n    }\n    \n    -- rare-type colors\n    modTable.rareColors = {\n        --[\"elite\"] = \"darkgoldenrod\",\n        [\"rareelite\"] = \"goldenrod\",\n        [\"rare\"] = \"silver\",\n        [\"worldboss\"] = \"darkmagenta\",\n    }\n    \n    modTable.npcColors = {\n        -- Mythic Plus Affixes\n        [229296] = modTable.config.affixEnabled and modTable.config.affixColor or nil, -- Orb of Ascendance\n        [229537] = modTable.config.affixEnabled and modTable.config.affixColor or nil, -- Void Emissary\n        \n        -- TWW2: Cinderbrew Meadery\n        [210264] = modTable.config.t3Mobs, -- Bee Wrangler\n        [214673] = modTable.config.t3Mobs, -- Flavor Scientist\n        [220060] = modTable.config.t3Mobs, -- Taste Tester\n        [220141] = modTable.config.t3Mobs, -- Royal Jelly Purveyor\n        [222964] = modTable.config.t3Mobs, -- Flavor Scientist\n        \n        [218671] = modTable.config.t4Mobs, -- Venture Co. Pyromaniac\n        \n        [210270] = modTable.config.t5Mobs, -- Brew Drop\n        [217126] = modTable.config.t5Mobs, -- Over-Indulged Patron\n        [218865] = modTable.config.t5Mobs, -- Bee-let\n        -- [219301] = modTable.config.t5Mobs, -- Brew Drop (boss)\n        [229691] = modTable.config.t5Mobs, -- Swarmbot\n        [223498] = modTable.config.t5Mobs, -- Bee-let\n        [223562] = modTable.config.t5Mobs, -- Brew Drop\n        \n        -- TWW2: Darkflame Cleft\n        [208745] = modTable.config.t1Mobs, -- The Candle King\n        [208747] = modTable.config.t1Mobs, -- The Darkness\n        [212412] = modTable.config.t1Mobs, -- Sootsnout\n        \n        [208456] = modTable.config.t3Mobs, -- Shuffling Horror\n        [210812] = modTable.config.t3Mobs, -- Royal Wicklighter\n        [213913] = modTable.config.t3Mobs, -- Kobold Flametender\n        [220815] = modTable.config.t3Mobs, -- Blazing Fiend\n        \n        [210148] = modTable.config.t5Mobs, -- Menial Laborer\n        [210810] = modTable.config.t5Mobs, -- Menial Laborer\n        [208457] = modTable.config.t5Mobs, -- Skittering Darkness\n        \n        -- TWW2: The MOTHERLODE!!\n        [130635] = modTable.config.t3Mobs, -- Stonefury\n        [130661] = modTable.config.t3Mobs, -- Venture Co. Earthshaper\n        [133432] = modTable.config.t3Mobs, -- Venture Co. Alchemist\n        [134232] = modTable.config.t3Mobs, -- Hired Assassin\n        [136470] = modTable.config.t3Mobs, -- Refreshment Vendor\n        \n        [130436] = modTable.config.t4Mobs, -- Off-Duty Laborer\n        [130437] = modTable.config.t4Mobs, -- Mine Rat\n        \n        [133963] = modTable.config.t5Mobs, -- Test Subject\n        [134005] = modTable.config.t5Mobs, -- Shalebiter\n        [136005] = modTable.config.t5Mobs, -- Rowdy Reveler\n        [136006] = modTable.config.t5Mobs, -- Rowdy Reveler\n        [137713] = modTable.config.t5Mobs, -- Big Money Crab\n        [138369] = modTable.config.t5Mobs, -- Footbomb Hooligan\n        \n        -- TWW2: Operation: Floodgate\n        [226398] = modTable.config.t1Mobs, -- Big M.O.M.M.A.\n        [230748] = modTable.config.t1Mobs, -- Darkfuse Bloodwarper\n        \n        [229069] = modTable.config.t3Mobs, -- Mechadrone Sniper\n        [229252] = modTable.config.t3Mobs, -- Darkfuse Hyena\n        [231223] = modTable.config.t3Mobs, -- Disturbed Kelp\n        [231312] = modTable.config.t3Mobs, -- Venture Co. Electrician\n        [231496] = modTable.config.t3Mobs, -- Venture Co. Diver\n        \n        [229686] = modTable.config.t4Mobs, -- Venture Co. Surveyor\n        [231014] = modTable.config.t4Mobs, -- Loaderbot\n        [231385] = modTable.config.t4Mobs, -- Darkfuse Inspector\n        \n        [227145] = modTable.config.t5Mobs, -- Waterworks Crocolisk\n        [231380] = modTable.config.t5Mobs, -- Undercrawler\n        \n        -- TWW2: Operation: Mechagon - Workshop\n        [144294] = modTable.config.t3Mobs, -- Mechagon Tinkerer\n        [151657] = modTable.config.t3Mobs, -- Bomb Tonk\n        \n        [144295] = modTable.config.t4Mobs, -- Mechagon Mechanic\n        \n        [144300] = modTable.config.t5Mobs, -- Mechagon Citizen\n        [144301] = modTable.config.t5Mobs, -- Living Waste\n        \n        -- TWW2: Priory of the Sacred Flame\n        [207939] = modTable.config.t1Mobs, -- Baron Braunpyke\n        [207940] = modTable.config.t1Mobs, -- Prioress Murrpray\n        [207946] = modTable.config.t1Mobs, -- Captain Dailcry\n        [211289] = modTable.config.t1Mobs, -- Taener Duelmal\n        [212827] = modTable.config.t1Mobs, -- High Priest Aemya\n        [239833] = modTable.config.t1Mobs, -- Elaena Emberlanz\n        \n        [206697] = modTable.config.t3Mobs, -- Devout Priest\n        [206698] = modTable.config.t3Mobs, -- Fanatical Conjuror\n        [221760] = modTable.config.t3Mobs, -- Risen Mage\n        \n        [206699] = modTable.config.t4Mobs, -- War Lynx\n        [206705] = modTable.config.t4Mobs, -- Arathi Footman\n        \n        [207943] = modTable.config.t5Mobs, -- Arathi Neophyte\n        [211140] = modTable.config.t5Mobs, -- Arathi Neophyte\n        [212838] = modTable.config.t5Mobs, -- Arathi Neophyte\n        \n        -- TWW2: The Rookery\n        [212793] = modTable.config.t1Mobs, -- Void Ascendant\n        \n        [207198] = modTable.config.t3Mobs, -- Cursed Thunderer\n        [207199] = modTable.config.t3Mobs, -- Cursed Rooktender\n        [207202] = modTable.config.t3Mobs, -- Void Fragment\n        [214439] = modTable.config.t3Mobs, -- Corrupted Oracle\n        \n        [219066] = modTable.config.t5Mobs, -- Afflicted Civilian\n        \n        -- TWW2: Theater of Pain\n        [162309] = modTable.config.t1Mobs, -- Kul'tharok\n        [164461] = modTable.config.t1Mobs, -- Sathel the Accursed\n        -- [164463] = modTable.config.t1Mobs, -- Paceran the Virulent\n        [164506] = modTable.config.t1Mobs, -- Ancient Captain\n        [165946] = modTable.config.t1Mobs, -- Mordretha, the Endless Empress\n        [169893] = modTable.config.t1Mobs, -- Nefarious Darkspeaker\n        \n        [160495] = modTable.config.t3Mobs, -- Maniacal Soulbinder\n        [170882] = modTable.config.t3Mobs, -- Bone Magus\n        [174197] = modTable.config.t3Mobs, -- Battlefield Ritualist\n        [174210] = modTable.config.t3Mobs, -- Blighted Sludge-Spewer\n        \n        [169875] = modTable.config.t4Mobs, -- Shackled Soul\n        [170690] = modTable.config.t4Mobs, -- Diseased Horror\n        \n        [163089] = modTable.config.t5Mobs, -- Disgusting Refuse\n        \n        -- TWW2: Liberation of Undermine\n        [228463] = modTable.config.t1Mobs, -- Reel Assistant\n        [231839] = modTable.config.t1Mobs, -- Scrapmaster\n        [232599] = modTable.config.t1Mobs, -- Reel Assistant\n        [233474] = modTable.config.t1Mobs, -- Gallagio Goon\n        \n        -- TWW1: Ara-Kara\n        [216364] = modTable.config.t1Mobs, -- Blood Overseer\n        [217531] = modTable.config.t1Mobs, -- Ixin\n        [217533] = modTable.config.t1Mobs, -- Atik\n        [218324] = modTable.config.t1Mobs, -- Nakt\n        \n        [216293] = modTable.config.t3Mobs, -- Trilling Attendant\n        [223253] = modTable.config.t3Mobs, -- Bloodstained Webmage\n        \n        [216333] = modTable.config.t4Mobs, -- Bloodstained Assistant\n        [216363] = modTable.config.t4Mobs, -- Reinforced Drone\n        \n        [215826] = modTable.config.t5Mobs, -- Bloodworker\n        [216336] = modTable.config.t5Mobs, -- Ravenous Crawler\n        [216337] = modTable.config.t5Mobs, -- Bloodworker\n        [216341] = modTable.config.t5Mobs, -- Jabbing Flyer\n        [218325] = modTable.config.t5Mobs, -- Swarming Flyer\n        [219221] = modTable.config.t5Mobs, -- Ravenous Crawler\n        \n        -- TWW1: City of Threads\n        [219984] = modTable.config.t1Mobs, -- Xeph'itik\n        [220196] = modTable.config.t1Mobs, -- Herald of Ansurek\n        [221102] = modTable.config.t1Mobs, -- Elder Shadeweaver\n        \n        [216326] = modTable.config.t3Mobs, -- Ascended Neophyte\n        [216339] = modTable.config.t3Mobs, -- Sureki Unnaturaler\n        [220195] = modTable.config.t3Mobs, -- Sureki Silkbinder\n        [223844] = modTable.config.t3Mobs, -- Covert Webmancer\n        [224732] = modTable.config.t3Mobs, -- Covert Webmancer\n        \n        [220193] = modTable.config.t4Mobs, -- Sureki Venomblade\n        [223182] = modTable.config.t4Mobs, -- Web Marauder\n        [223357] = modTable.config.t4Mobs, -- Sureki Conscript\n        \n        [216329] = modTable.config.t5Mobs, -- Congealed Droplet\n        [220199] = modTable.config.t5Mobs, -- Battle Scarab\n        \n        -- TWW1: Grim Batol\n        [40319] = modTable.config.t1Mobs, -- Drahga Shadowburner\n        \n        [40167] = modTable.config.t3Mobs, -- Twilight Beguiler\n        [224219] = modTable.config.t3Mobs, -- Twilight Earthcaller\n        [224271] = modTable.config.t3Mobs, -- Twilight Warlock\n        \n        [224853] = modTable.config.t5Mobs, -- Mutated Hatchling\n        \n        -- TWW1: Mists of Tirna Scithe\n        [164501] = modTable.config.t1Mobs, -- Mistcaller\n        [164567] = modTable.config.t1Mobs, -- Ingra Maloch\n        [167111] = modTable.config.t1Mobs, -- Spinemaw Staghorn\n        \n        [164921] = modTable.config.t3Mobs, -- Drust Harvester\n        [166275] = modTable.config.t3Mobs, -- Mistveil Shaper\n        [166299] = modTable.config.t3Mobs, -- Mistveil Tender\n        \n        [164920] = modTable.config.t4Mobs, -- Drust Soulcleaver\n        \n        [167117] = modTable.config.t5Mobs, -- Spinemaw Larva\n        \n        -- TWW1: Siege of Boralus\n        [128969] = modTable.config.t1Mobs, -- Ashvane Commander\n        \n        [129367] = modTable.config.t3Mobs, -- Bilge Rat Tempest\n        [129370] = modTable.config.t3Mobs, -- Irontide Waveshaper\n        [135241] = modTable.config.t3Mobs, -- Bilge Rat Pillager\n        [144071] = modTable.config.t3Mobs, -- Irontide Waveshaper\n        \n        [133990] = modTable.config.t5Mobs, -- Scrimshaw Gutter\n        [135258] = modTable.config.t5Mobs, -- Irontide Curseblade\n        [138002] = modTable.config.t5Mobs, -- Scrimshaw Gutter\n        [138247] = modTable.config.t5Mobs, -- Irontide Curseblade\n        \n        -- TWW1: The Dawnbreaker\n        [210966] = modTable.config.t1Mobs, -- Sureki Webmage\n        [211087] = modTable.config.t1Mobs, -- Speaker Shadowcrown\n        [211089] = modTable.config.t1Mobs, -- Anub'ikkaj\n        [213885] = modTable.config.t1Mobs, -- Nightfall Dark Architect\n        [213932] = modTable.config.t1Mobs, -- Sureki Militant\n        [213937] = modTable.config.t1Mobs, -- Rasha'nan\n        [214762] = modTable.config.t1Mobs, -- Nightfall Commander\n        \n        [213892] = modTable.config.t3Mobs, -- Nightfall Shadowmage\n        [213893] = modTable.config.t3Mobs, -- Nightfall Darkcaster\n        [213905] = modTable.config.t3Mobs, -- Animated Darkness\n        [223994] = modTable.config.t3Mobs, -- Nightfall Shadowmage\n        [228540] = modTable.config.t3Mobs, -- Nightfall Shadowmage\n        \n        [213894] = modTable.config.t4Mobs, -- Nightfall Curseblade\n        [213895] = modTable.config.t4Mobs, -- Nightfall Shadowalker\n        \n        -- TWW1: The Stonevault\n        [213217] = modTable.config.t1Mobs, -- Speaker Brokk\n        \n        [212389] = modTable.config.t3Mobs, -- Cursedheart Invader\n        [212403] = modTable.config.t3Mobs, -- Cursedheart Invader\n        [212453] = modTable.config.t3Mobs, -- Ghastly Voidsoul\n        [213338] = modTable.config.t3Mobs, -- Forgebound Mender\n        [214066] = modTable.config.t3Mobs, -- Cursedforge Stoneshaper\n        [214350] = modTable.config.t3Mobs, -- Turned Speaker\n        [221979] = modTable.config.t3Mobs, -- Void Bound Howler\n        [224962] = modTable.config.t3Mobs, -- Cursedforge Mender\n        \n        [212764] = modTable.config.t4Mobs, -- Engine Speaker\n        [212405] = modTable.config.t4Mobs, -- Aspiring Forgehand\n        \n        -- TWW1: The Necrotic Wake\n        [162693] = modTable.config.t1Mobs, -- Nalthor the Rimebinder\n        [163157] = modTable.config.t1Mobs, -- Amarth\n        [165137] = modTable.config.t1Mobs, -- Zolramus Gatekeeper\n        [165824] = modTable.config.t1Mobs, -- Nar'zudah\n        [165919] = modTable.config.t1Mobs, -- Skeletal Marauder\n        [173044] = modTable.config.t1Mobs, -- Stitching Assistant\n        \n        [163126] = modTable.config.t3Mobs, -- Brittlebone Mage\n        [163128] = modTable.config.t3Mobs, -- Zolramus Sorcerer\n        [163618] = modTable.config.t3Mobs, -- Zolramus Necromancer\n        [165222] = modTable.config.t3Mobs, -- Zolramus Bonemender\n        [165872] = modTable.config.t3Mobs, -- Flesh Crafter\n        [166302] = modTable.config.t3Mobs, -- Corpse Harvester\n        [173016] = modTable.config.t3Mobs, -- Corpse Collector\n        \n        [163121] = modTable.config.t4Mobs, -- Stitched Vanguard\n        [163619] = modTable.config.t4Mobs, -- Zolramus Bonecarver\n        \n        [165138] = modTable.config.t5Mobs, -- Blight Bag\n        [166264] = modTable.config.t5Mobs, -- Spare Parts\n        [166266] = modTable.config.t5Mobs, -- Spare Parts #2\n        [171500] = modTable.config.t5Mobs, -- Shuffling Corpse\n        \n        -- TWW1: Nerub-ar Palace\n        [217491] = modTable.config.t1Mobs, -- Skeinspinner Takazj\n        \n        \n        -- TWW: Awakening the Machine\n        [229695] = modTable.config.t3Mobs, -- Corrupted Machinist\n        \n        [229769] = modTable.config.t4Mobs, -- Medbot\n        \n        -- TWW: Delves\n        [221896] = modTable.config.t1Mobs, -- Web General Ab'enar\n        [217208] = modTable.config.t1Mobs, -- Zekvir\n        [228030] = modTable.config.t1Mobs, -- Sir Finley Mrrgglton\n        \n        [208244] = modTable.config.t3Mobs, -- Nerubian Threadmancer\n        [208242] = modTable.config.t3Mobs, -- Nerubian Darkcaster\n        [203878] = modTable.config.t3Mobs, -- Kobold Mystic\n        -- [204127] = modTable.config.t3Mobs, -- Kobold Taskfinder\n        \n        [226625] = modTable.config.t5Mobs, -- Cave Skipper\n    }\n    \n    modTable.aggroTracked = {\n        -- Some Mobs that doesn't have aggro or are important to track their aggro\n        [80875] = true, -- Bombsquad\n        [150547] = true, -- Scrapbone Grunter\n        [152033] = true, -- Inconspicuous Plant\n        [152703] = true, -- Walkie Shockie X1\n        [153196] = true, -- Scrapbone Grunter\n        [163746] = true, -- Walkie Shockie X1\n        [174773] = true, -- Spiteful Shade\n        [177500] = true, -- Corsair Brute\n        [178388] = true, -- Bazaar Strongarm\n    }\n    \n    function modTable.UpdateColor (unitFrame, envTable)\n        if not unitFrame or unitFrame.IsNpcWithoutHealthbar or unitFrame.IsFriendlyPlayerWithoutHealthbar or unitFrame.DenyColorChange then return end\n        \n        local forceAggroColor = modTable.aggroTracked [unitFrame.namePlateNpcId] or modTable.aggroTracked [unitFrame.namePlateUnitName] or modTable.aggroTracked [unitFrame.namePlateUnitNameLower]\n        \n        if forceAggroColor then\n            local unit = unitFrame.targetUnitID\n            if UnitExists(unit) and UnitIsPlayer(unit) then\n                if UnitGroupRolesAssigned(unit) == \"TANK\" then\n                    if UnitIsUnit(unit, \"player\") or unitFrame.namePlateThreatStatus == 3 then\n                        Plater.SetNameplateColor (unitFrame, Plater.db.profile.tank.colors.aggro)\n                        return\n                    else\n                        if Plater.PlayerIsTank then\n                            Plater.SetNameplateColor (unitFrame, Plater.db.profile.tank.colors.anothertank)\n                            return\n                        end\n                    end\n                else\n                    if UnitIsUnit(unit, \"player\") or unitFrame.namePlateThreatStatus == 3 then\n                        Plater.SetNameplateColor (unitFrame, Plater.db.profile.dps.colors.aggro)\n                        return\n                    end\n                end\n            end\n        end\n        \n        if (modTable.useThreatColors and Plater.IsInCombat() and unitFrame.InCombat) then\n            if (Plater.PlayerIsTank) then\n                if (not unitFrame.namePlateThreatIsTanking or unitFrame.namePlateThreatStatus == 2) then\n                    return\n                end\n            else\n                if (unitFrame.namePlateThreatIsTanking or unitFrame.namePlateThreatStatus == 1) then\n                    return\n                end\n            end\n        end\n        \n        if modTable.useTargetColor then\n            local unitIsPlayer = unitFrame.ActorType == \"friendlyplayer\" or unitFrame.ActorType == \"enemyplayer\"\n            if unitFrame.namePlateIsTarget then\n                if not unitIsPlayer or (not modTable.ignoreTargetColorOnPlayers and unitIsPlayer) then\n                    if modTable.colorHealthBar then\n                        Plater.SetNameplateColor (unitFrame, modTable.targetColor)\n                    end\n                    if modTable.colorNameText then\n                        Plater:SetFontColor (unitFrame.unitName, Plater:ParseColors(modTable.targetColor))\n                    end\n                    envTable.HasRaidMark = nil\n                    envTable.isTarget = true\n                    envTable.wasTarget = false\n                end\n                return\n            elseif envTable.isTarget then\n                envTable.isTarget = false\n                envTable.wasTarget = true\n            end\n        end\n        \n        if modTable.useFocusColor then\n            if UnitIsUnit (unitFrame.namePlateUnitToken, \"focus\") then\n                if modTable.colorHealthBar then\n                    Plater.SetNameplateColor (unitFrame, modTable.focusColor)\n                end\n                if modTable.colorNameText then\n                    Plater:SetFontColor (unitFrame.unitName, Plater:ParseColors(modTable.focusColor))\n                end\n                envTable.HasRaidMark = nil\n                envTable.isFocus = true\n                envTable.wasFocus = false\n                return\n            elseif envTable.isFocus then\n                envTable.isFocus = false\n                envTable.wasFocus = true\n            end\n        end\n        \n        -- from \"Color by Raid Mark\"\n        local raidMark = nil\n        if modTable.showRaidMarkColors and unitFrame.unit then\n            raidMark = Plater.GetRaidMark (unitFrame)\n        end\n        \n        if (raidMark and modTable.colorByMark [raidMark]) then\n            \n            if modTable.colorHealthBar then\n                Plater.SetNameplateColor (unitFrame, modTable.colorByMark [raidMark])\n            end\n            if modTable.colorNameText then\n                Plater:SetFontColor (unitFrame.unitName, Plater:ParseColors(modTable.colorByMark [raidMark]))\n            end\n            envTable.HasRaidMark = true\n            return\n        end\n        \n        --attempt to get the color from the unit color list\n        local color = modTable.npcColors [unitFrame.namePlateUnitNameLower] or modTable.npcColors [unitFrame.namePlateUnitName] or modTable.npcColors [unitFrame.namePlateNpcId] or (modTable.colorRares and modTable.rareColors[UnitClassification(unitFrame.namePlateUnitToken)])\n        \n        -- Automatically detect T2 mobs by level\n        if (not color) then\n            local playerLevel = UnitLevel(\"player\")\n            local unitLevel = UnitLevel(unitFrame.unit)\n            \n            if (Plater.ZoneInstanceType == \"party\" or Plater.ZoneInstanceType == \"scenario\") then\n                -- In dungeons, anything higher level than the player is a lieutenant/boss\n                if (playerLevel < unitLevel) then\n                    color = modTable.config.t2Mobs\n                end\n            elseif (Plater.ZoneInstanceType == \"raid\") then\n                -- In raids, anything two or more levels higher than the player or ?? (-1) is a lieutenant/boss\n                if ((playerLevel < unitLevel - 1) or (unitLevel == -1)) then\n                    color = modTable.config.t2Mobs\n                end\n            end\n        end\n        \n        --if the color exists, set the health bar color\n        if (color) then\n            \n            if modTable.colorHealthBar then\n                Plater.SetNameplateColor (unitFrame, color)\n            end\n            if modTable.colorNameText then\n                Plater:SetFontColor (unitFrame.unitName, Plater:ParseColors(color))\n            end\n            envTable.HasRaidMark = nil\n            \n        elseif envTable.HasRaidMark or envTable.wasTarget or envTable.wasFocus then\n            \n            if unitIsPlayer then\n                Plater.FindAndSetNameplateColor (unitFrame)\n            else\n                Plater.RefreshNameplateColor (unitFrame)\n            end\n            if modTable.colorNameText then\n                --Plater.UpdatePlateText (unitFrame.PlateFrame, Plater.db.profile.plate_config[unitFrame.ActorType], false)\n                modTable.resetNameColor(unitFrame)\n            end\n            envTable.HasRaidMark = nil\n            envTable.wasTarget = false\n            envTable.wasFocus = false\n            \n        end\n    end\n    \n    function modTable.resetNameColor(unitFrame)\n        local plateFrame = unitFrame.PlateFrame\n        local nameString = unitFrame.unitName\n        local plateConfigs = Plater.db.profile.plate_config[unitFrame.ActorType]\n        local ACTORTYPE_FRIENDLY_PLAYER = \"friendlyplayer\"\n        \n        if (Plater.db.profile.plate_config [ACTORTYPE_FRIENDLY_PLAYER].actorname_use_guild_color and plateFrame.playerGuildName == Plater.PlayerGuildName) then\n            \n            Plater:SetFontColor (nameString, unpack(Plater.db.profile.plate_config [ACTORTYPE_FRIENDLY_PLAYER].actorname_guild_color))\n            \n        elseif (Plater.db.profile.plate_config [ACTORTYPE_FRIENDLY_PLAYER].actorname_use_friends_color and Plater.FriendsCache [plateFrame.namePlateUnitName]) then\n            \n            Plater:SetFontColor (nameString, unpack(Plater.db.profile.plate_config [ACTORTYPE_FRIENDLY_PLAYER].actorname_friend_color))\n            \n        elseif (plateFrame.actorType == ACTORTYPE_FRIENDLY_PLAYER and Plater.db.profile.plate_config [ACTORTYPE_FRIENDLY_PLAYER].actorname_use_class_color) then\n            local _, unitClass = UnitClass (unitFrame.namePlateUnitToken)\n            \n            if (unitClass) then\n                local color = RAID_CLASS_COLORS [unitClass]\n                Plater:SetFontColor (nameString, color.r, color.g, color.b)\n            else\n                Plater:SetFontColor (nameString, plateConfigs.actorname_text_color)\n            end\n            \n        else\n            Plater:SetFontColor (nameString, plateConfigs.actorname_text_color)\n        end\n    end\n    \nend\n\n\n\n\n",
                        ["Target Changed"] =
                        "function (self, unitId, unitFrame, envTable, modTable)\n    if modTable.useTargetColor then\n        modTable.UpdateColor (unitFrame, envTable)\n    end\nend\n\n\n\n\n\n\n"
